# Add some debugging
def debug_show(self, file=None):
    print(f"\n=== UsageError.show ===")
    print(f"self.ctx.command_path = {repr(self.ctx.command_path)}")
    print(f"self.ctx.info_name = {repr(self.ctx.info_name)}")
    print(f"self.ctx.help_option_names = {self.ctx.help_option_names}")
    print(f"self.ctx.command.get_help_option_names(self.ctx) = {self.ctx.command.get_help_option_names(self.ctx)}")

    if self.ctx is not None and self.ctx.command.get_help_option(self.ctx) is not None:
        hint = "Try '{command} {option}' for help.".format(
            command=self.ctx.command_path, option=self.ctx.help_option_names[0]
        )
        print(f"\nHint using self.ctx.help_option_names[0]: {hint}")

